head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.bzProcsNo = "";               // 업무처리번호 — 부모 openPopup data (원본 vBzProcsNo, §1.2)
scwin.prelmInvstgBzProcsNo = "";    // 예비심사 업무처리번호 — 상세가 없을 때 기본값 원천 (원본 vPRELM_INVSTG_BZ_PROCS_NO)
// 원본 : W-Craft 1차 변환본 ULDSTF05106.xml (API 적용 개발 사본, meta_asisFileNm ULDSTF05106_read.gfm — 원본 gfm 은 저장소에 없음)
/*
 * 화면 동작
 *  - 부모(05101 예비심사관리 · 05105 신규상장목록 · 05113 신규상장목록등록)가 openPopup data 로 업무처리번호를 넘기면 종류주식 상세를 조회한다.
 *  - 상세가 아직 없으면 예비심사 업무처리번호의 상세를 기본값으로 불러와 신규(저장) 상태가 되고, 있으면 수정 상태가 된다.
 *  - 이익배당·잔여재산분배·의결권배제·의결권제한·상환·전환 체크에 따라 하위 입력 영역을 펼치고 접는다.
 *  - 저장·수정 뒤 다시 조회한다. 닫을 때 부모에게 돌려주는 값은 없다(원본도 부모를 다시 조회하지 않는다).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05106/ULDSTF05106.md (§번호는 이 문서의 절)
 */

// 버튼 역할 → 버튼 id ($c.util.setButtonState, 원본 buttonSet.setSaveInfo/setUpdateInfo)
scwin.BTN_MAP = {
    save : "btn_Save",      // [저장]
    modify : "btn_Update"   // [수정]
};

// 체크박스 여부 키 — 체크 "Y" / 해제 "N" (마크업 trueValue·falseValue, §2.2)
scwin.YN_KEYS = [
    "proftDivYn", "cmstkPct1DivYn", "lwstDivRtDscYn", "miscDivYn", "cashDivYn", "partctpYn", "acctpYn", "ndivtmVoterghtYn",
    "remainProprtDistrYn", "voterghtExcldYn", "voterghtLmtYn",
    "redmptYn", "comRedmptRghtYn", "comCashRedmptYn", "shrhdRedmptRghtYn", "shrhdCashRedmptYn",
    "convYn", "comConvRghtYn", "shrhdConvRghtYn"
];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05106.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 파라미터 수신 → 달력 바인딩 → 상세 조회(업무처리번호가 있을 때) → 체크 상태에 맞춰 영역 표시.
 * (원본 init/gform_onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 부모가 넘긴 data (원본 getParent().scwin.vBzProcsNo 등 직접 읽기 → openPopup data, 가이드 §6.5)
    //    listProcsStatCd·mktTpCd 도 오지만 원본도 쓰지 않는다(§1.2).
    const param = $c.data.getParameter() ?? {};
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.prelmInvstgBzProcsNo = String(param.prelmInvstgBzProcsNo ?? "");

    // 2) 달력 검사 바인딩(1회) — 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.compareFromToDate(tbx_COM_REDMPT_PD_STRT_DD, tbx_COM_REDMPT_PD_END_DD, ["회사 상환기간 시작일", "회사 상환기간 종료일"]);
    $c.date.compareFromToDate(tbx_SHRHD_REDMPT_PD_STRT_DD, tbx_SHRHD_REDMPT_PD_END_DD, ["주주 상환기간 시작일", "주주 상환기간 종료일"]);
    $c.date.compareFromToDate(tbx_COM_CONV_PD_STRT_DD, tbx_COM_CONV_PD_END_DD, ["회사 전환기간 시작일", "회사 전환기간 종료일"]);
    $c.date.compareFromToDate(tbx_SHRHD_CONV_PD_STRT_DD, tbx_SHRHD_CONV_PD_END_DD, ["주주 전환기간 시작일", "주주 전환기간 종료일"]);

    // 3) 상세 조회 — 업무처리번호가 없으면 빈 신규 상태(원본 KIND_STK_DTL_INOUT 헤더 빈 행)
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        dma_Item.setEmptyValue();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    } else {
        await scwin.selectDetail();
    }

    // 4) 체크 값 정리 + 하위 영역 표시
    scwin.applyForm();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
