 * @description [이익배당] 체크 — 배당 상세 영역(panel_1)을 펼치거나 접는다. (원본 chk_PROFT_DIV_YN onclick — §4)
 * @param {Object} info 이벤트 정보
 * @returns
 * @hidden N
 */
scwin.chk_PROFT_DIV_YN_onviewchange = function (info) {
    try {
        scwin.showPanel(panel_1, chk_PROFT_DIV_YN.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05106.chk_PROFT_DIV_YN_onviewchange" });
    }
};

