///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식 상세 1건 조회 — 응답 body 를 dma_Item 에 받는다. 받기 전에 비워 앞 건 값이 남지 않게 한다.
 * (원본 dts_Item.DataID = /KindStk.do?method=selectKindStkDtl … Reset — §5.1)
 * @param {String} bzProcsNo 조회할 업무처리번호
 * @returns {Promise<Boolean>} 통신 성공 여부
 * @hidden N
 */
scwin.selectOne = async function (bzProcsNo) {
    const sbmOptions = {
        id : "sbm_selectOne",
        action : "/api/listing/lstproc/stock/issuance-manage-kindstk-detail/select-one",
        method : "get",
        target : "dma_Item=body",
        isProcessMsg : false
    };

    dma_Item.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : bzProcsNo });
    if (result?.skipped) return false;    // 진행 중 처리가 있어 이번 호출은 건너뜀
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종류주식 상세 등록(I)·수정(U) — dma_Item 을 ref 로 보낸다. 성공하면 안내 뒤 다시 조회하고, 실패하면 MSG-A002.
 * (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.2, §5.3)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        action : (trJob === "I") ? "/api/listing/lstproc/kind/listing-review/kind-stk/register"
                                 : "/api/listing/lstproc/kind/listing-review/kind-stk/modify",
        method : "post",
        ref : "dma_Item",
        isProcessMsg : false
    };

    // 원본 fn_trs — 업무처리번호를 부모가 넘긴 값으로 채운다(신규는 예비심사 상세를 기본값으로 불러와 비워 둔 상태).
    dma_Item.set("bzProcsNo", scwin.bzProcsNo);

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    // TODO: register·modify 의 응답 구조(completeYn 등)가 화면에 정의돼 있지 않아 통신 성공만으로 판정한다 (§10 #2)
    if (result?.responseJSON?.success !== true) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));
    await scwin.selectDetail();
    scwin.applyForm();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상세 조회와 버튼 상태. 이 업무처리번호의 상세가 있으면 수정 상태, 없으면 신규 상태로 두고
 * 예비심사 업무처리번호의 상세를 기본값으로 불러온다(불러온 건의 업무처리번호는 비운다). 그것도 없으면 빈 값.
 * (원본 fn_read_sync — §5.1, §1.4 업무 1)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function () {
    await scwin.selectOne(scwin.bzProcsNo);

    if (!$c.util.isEmpty(dma_Item.get("bzProcsNo"))) {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
        return;
    }

    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);

    // 05101(예비심사관리)은 예비심사 업무처리번호를 넘기지 않는다 — 빈 값이면 기본값 조회를 건너뛴다 (§1.2)
    if ($c.util.isEmpty(scwin.prelmInvstgBzProcsNo)) return;

    await scwin.selectOne(scwin.prelmInvstgBzProcsNo);
    if ($c.util.isEmpty(dma_Item.get("bzProcsNo"))) {
        dma_Item.setEmptyValue();
    } else {
        dma_Item.set("bzProcsNo", "");
    }
};

/**
 * @method
 * @name scwin.applyForm
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 뒤 체크 값을 "Y"/"N" 으로 맞추고, 체크 상태에 따라 하위 영역을 펼치거나 접는다.
 * (원본 initForm — 빈 값을 0 으로 채운 뒤 showObj, §6.1)
 * @returns
 * @hidden N
 */
scwin.applyForm = function () {
    // 원본 Gauce 는 체크 1 / 해제 0 이었다. 서버가 "1" 로 줘도 체크로 보이게 "Y"/"N" 으로 맞춘다 (§8 #2, §10 #1)
    scwin.YN_KEYS.forEach(key => {
        const value = String(dma_Item.get(key) ?? "");
        dma_Item.set(key, (value === "Y" || value === "1") ? "Y" : "N");
    });

    // 상위 영역이 접히면 하위 영역(panel_6·7 ⊂ panel_5, panel_9·10 ⊂ panel_8)도 함께 가려진다
    scwin.showPanel(panel_1, dma_Item.get("proftDivYn"));
    scwin.showPanel(panel_2, dma_Item.get("remainProprtDistrYn"));
    scwin.showPanel(panel_3, dma_Item.get("voterghtExcldYn"));
    scwin.showPanel(panel_4, dma_Item.get("voterghtLmtYn"));
    scwin.showPanel(panel_5, dma_Item.get("redmptYn"));
    scwin.showPanel(panel_6, dma_Item.get("comRedmptRghtYn"));
    scwin.showPanel(panel_7, dma_Item.get("shrhdRedmptRghtYn"));
    scwin.showPanel(panel_8, dma_Item.get("convYn"));
    scwin.showPanel(panel_9, dma_Item.get("comConvRghtYn"));
    scwin.showPanel(panel_10, dma_Item.get("shrhdConvRghtYn"));
};

/**
 * @method
 * @name scwin.showPanel
 * @author Inswave
 * @date 2026. 10. 29
 * @description 체크 값이 "Y" 이면 영역을 보이고 아니면 감춘다. (원본 $c.stf.showObj(panel, flag) — 규칙 V29)
 * @param {Object} panel 영역 그룹 컴포넌트
 * @param {String} yn 체크 값
 * @returns
 * @hidden N
 */
scwin.showPanel = function (panel, yn) {
    if (yn === "Y") {
        panel.show("");
    } else {
        panel.hide();
    }
};

/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 검증. ① 상위 체크 6개가 모두 해제면 안내하고 중단 ② [상환]·[전환]이 해제면
 * 하위 값을 지운다는 확인을 받고 지운다(취소하면 중단). (원본 fn_checkForm — §6.2)
 * @returns {Promise<Boolean>} 진행 여부
 * @hidden N
 */
scwin.checkForm = async function () {
    // ① 원본 PROFT_DIV_YN·REMAIN_PROPRT_DISTR_YN·VOTERGHT_EXCLD_YN·VOTERGHT_LMT_YN·REDMPT_YN·CONV_YN 가 모두 'N' (개발 사본에서 빠졌던 검사 복원, §8 #4)
    const topKeys = ["proftDivYn", "remainProprtDistrYn", "voterghtExcldYn", "voterghtLmtYn", "redmptYn", "convYn"];
    if (topKeys.every(key => dma_Item.get(key) !== "Y")) {
        await $c.win.alert("입력된 종류주식 상세내역이 없습니다.\n입력 데이터를 확인해 주십시오.");
        return false;
    }

    // ② 상환 해제 — 하위 값 제거 (원본이 빠뜨린 회사 상환기간 종료일도 함께 지운다, §8 #5)
    if (dma_Item.get("redmptYn") !== "Y") {
        if (!await $c.win.confirm("[상환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) return false;
        dma_Item.set("comRedmptRghtYn", "N");
        dma_Item.set("comRedmptPdStrtDd", "");
        dma_Item.set("comRedmptPdEndDd", "");
        dma_Item.set("comCashRedmptYn", "N");
        dma_Item.set("comRedmptRemk", "");
        dma_Item.set("shrhdRedmptRghtYn", "N");
        dma_Item.set("shrhdRedmptPdStrtDd", "");
        dma_Item.set("shrhdRedmptPdEndDd", "");
        dma_Item.set("shrhdCashRedmptYn", "N");
        dma_Item.set("shrhdRedmptRemk", "");
    }

    // ③ 전환 해제 — 하위 값 제거 (개발 사본의 comConvRdStrtDd·comConvRdEndDd 오타 키를 바로잡음, §8 #6)
    if (dma_Item.get("convYn") !== "Y") {
        if (!await $c.win.confirm("[전환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) return false;
        dma_Item.set("comConvRghtYn", "N");
        dma_Item.set("comConvRto", 0);
        dma_Item.set("comConvObjStkContn", "");
        dma_Item.set("comConvPdStrtDd", "");
        dma_Item.set("comConvPdEndDd", "");
        dma_Item.set("comConvRemk", "");
        dma_Item.set("shrhdConvRghtYn", "N");
        dma_Item.set("shrhdConvRto", 0);
        dma_Item.set("shrhdConvObjStkContn", "");
        dma_Item.set("shrhdConvPdStrtDd", "");
        dma_Item.set("shrhdConvPdEndDd", "");
        dma_Item.set("shrhdConvRemk", "");
    }
    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 저장. 검증 → 확인(MSG-A006) → 업무처리번호 14자리 확인(MSG-0010) → 등록. (원본 fn_save — §6.3, §1.4 업무 2)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkForm()) return;
    if (!await $c.lc.isProcess("I")) return;

    if (scwin.bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    await scwin.saveTrs("I");
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정. 검증 → 확인(MSG-A006) → 수정. (원본 fn_update — §6.4, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    if (!await scwin.checkForm()) return;
    if (!await $c.lc.isProcess("U")) return;

    await scwin.saveTrs("U");
};
